class Scope:
    """A lexical scope: a name table plus a link to its parent."""

    def __init__(
        self,
        name: str,
        parent: Optional["Scope"] = None,
        op: Optional[Operation] = None,
    ) -> None:
        self.name = name
        self.parent = parent
        self.op = op
        self.entries: Dict[str, SymbolEntry] = {}
        self.children: List["Scope"] = []
        if parent is not None:
            parent.children.append(self)

    # -- definitions ------------------------------------------------------
    def define(self, entry: SymbolEntry) -> SymbolEntry:
        entry.scope_name = self.name
        self.entries[entry.name] = entry
        return entry

    def lookup_local(self, name: str) -> Optional[SymbolEntry]:
        return self.entries.get(name.lstrip("@%"))

    def lookup(self, name: str) -> Optional[SymbolEntry]:
        """Search this scope then every enclosing one."""
        scope: Optional[Scope] = self
        key = name.lstrip("@%")
        while scope is not None:
            found = scope.entries.get(key)
            if found is not None:
                return found
            scope = scope.parent
        return None

    def find_child(self, name: str) -> Optional["Scope"]:
        for child in self.children:
            if child.name == name:
                return child
        return None

    # -- queries ----------------------------------------------------------
    def names(self) -> List[str]:
        return sorted(self.entries)

    @property
    def depth(self) -> int:
        return 0 if self.parent is None else self.parent.depth + 1

    def walk(self) -> Iterator["Scope"]:
        yield self
        for child in self.children:
            yield from child.walk()

    def __len__(self) -> int:
        return len(self.entries)

    def __contains__(self, name: str) -> bool:
        return self.lookup(name) is not None

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<Scope {self.name!r} entries={len(self.entries)} children={len(self.children)}>"


@dataclass
class SymbolResolution:
    """The result of running :class:`SymbolResolver`."""

    root_scope: Scope
    definitions: Dict[str, SymbolEntry] = field(default_factory=dict)
    references: List[SymbolReference] = field(default_factory=list)
    values: Dict[str, SymbolEntry] = field(default_factory=dict)
    errors: List[str] = field(default_factory=list)

    # -- counts -----------------------------------------------------------
    @property
    def num_resolved(self) -> int:
        """How many symbol definitions were bound into the scope tree."""
        return len(self.definitions)

    @property
    def num_references(self) -> int:
        return len(self.references)

    @property
    def num_references_resolved(self) -> int:
        return sum(1 for ref in self.references if ref.is_resolved)

    @property
    def unresolved(self) -> List[SymbolReference]:
        return [ref for ref in self.references if not ref.is_resolved]

    @property
    def is_complete(self) -> bool:
        return not self.unresolved and not self.errors

    # -- lookup -----------------------------------------------------------
    def names(self) -> List[str]:
        return sorted(self.definitions)

    def lookup(self, name: str) -> Optional[SymbolEntry]:
        key = name.lstrip("@%")
        return self.definitions.get(key) or self.root_scope.lookup(key)

    def operation(self, name: str) -> Optional[Operation]:
        entry = self.lookup(name)
        return entry.op if entry is not None else None

    def scope_for(self, name: str) -> Optional[Scope]:
        return self.root_scope.find_child(name.lstrip("@%"))

    def __len__(self) -> int:
        return len(self.definitions)

    def __contains__(self, name: str) -> bool:
        return self.lookup(name) is not None

    def to_text(self) -> str:
        lines: List[str] = []
        for scope in self.root_scope.walk():
            indent = "  " * scope.depth
            lines.append(f"{indent}{scope.name}:")
            for name in scope.names():
                lines.append(f"{indent}  {scope.entries[name]}")
        for ref in self.references:
            lines.append(str(ref))
        return "\n".join(lines)


class SymbolResolver:
    """Builds the scope tree for an operation and binds every reference."""

    def __init__(self, root: Operation) -> None:
        self.root = root
        self._resolution: Optional[SymbolResolution] = None

    # -- entry point ------------------------------------------------------
    def resolve(self) -> SymbolResolution:
        """Run the analysis (cached: repeated calls return the same result)."""
        if self._resolution is not None:
            return self._resolution

        root_name = SymbolTable.get_symbol_name(self.root) or self._default_root_name()
        root_scope = Scope(root_name, op=self.root)
        resolution = SymbolResolution(root_scope=root_scope)

        self._collect_definitions(self.root, root_scope, resolution)
        self._collect_references(self.root, resolution)
        self._bind_references(resolution)

        self._resolution = resolution
        return resolution

    def _default_root_name(self) -> str:
        return "module" if self.root.name == "builtin.module" else self.root.name

    # -- definitions ------------------------------------------------------
    def _collect_definitions(
        self, op: Operation, scope: Scope, resolution: SymbolResolution
    ) -> None:
        for region in op.regions:
            for block in region.blocks:
                self._collect_block(block, scope, resolution)

    def _collect_block(
        self, block: Block, scope: Scope, resolution: SymbolResolution
    ) -> None:
        if block.label:
            scope.define(SymbolEntry(block.label, SymbolKind.BLOCK))
        for child in block.operations:
            symbol = SymbolTable.get_symbol_name(child)
            if symbol is not None:
                entry = scope.define(

                entry = scope.define(
                    SymbolEntry(
                        symbol,
                        SymbolKind.for_operation(child),
                        op=child,
                        type=self._declared_type(child),
                    )
                )
                if entry.is_symbol_definition:
                    resolution.definitions[symbol] = entry
                nested = Scope(symbol, parent=scope, op=child)
                self._collect_arguments(child, nested, resolution)
                self._collect_definitions(child, nested, resolution)
                continue

            self._record_results(child, scope, resolution)
            # Operations without a symbol still own regions (``sv.if``,
            # ``fsm.state``); their bodies share the enclosing scope.
            self._collect_definitions(child, scope, resolution)

    def _collect_arguments(
        self, op: Operation, scope: Scope, resolution: SymbolResolution
    ) -> None:
        kind = (
            SymbolKind.PORT
            if op.name in ("hw.module", "hw.module.extern", "firrtl.module", "sv.module")
            else SymbolKind.ARGUMENT
        )
        for region in op.regions:
            for block in region.blocks:
                for index, argument in enumerate(block.arguments):
                    name = argument.name or f"arg{index}"
                    entry = scope.define(
                        SymbolEntry(name, kind, op=op, value=argument, type=argument.type)
                    )
                    resolution.values[entry.qualified_name] = entry

    def _record_results(
        self, op: Operation, scope: Scope, resolution: SymbolResolution
    ) -> None:
        stateful = op.name.startswith("seq.") or op.name in ("firrtl.reg", "sv.reg")
        kind = SymbolKind.REGISTER if stateful else SymbolKind.VALUE
        for result in op.results:
            if not result.name:
                continue
            entry = scope.define(
                SymbolEntry(result.name, kind, op=op, value=result, type=result.type)
            )
            resolution.values[entry.qualified_name] = entry

    @staticmethod
    def _declared_type(op: Operation) -> Optional[Type]:
        attr = op.attributes.get("function_type")
        return attr.value if attr is not None else None

    # -- references -------------------------------------------------------
    def _collect_references(
        self, op: Operation, resolution: SymbolResolution
    ) -> None:
        def visit(candidate: Operation) -> None:
            for name in REFERENCE_ATTRIBUTES:
                attr = candidate.attributes.get(name)
                symbol = self._symbol_of(attr)
                if symbol is None:
                    continue
                resolution.references.append(
                    SymbolReference(symbol, candidate, attribute=name)
                )

        op.walk(visit)

    @staticmethod
    def _symbol_of(attr: Optional[Attribute]) -> Optional[str]:
        if isinstance(attr, FlatSymbolRefAttr):
            return str(attr.value)
        if isinstance(attr, StringAttr):
            return attr.value.lstrip("@")
        return None

    def _bind_references(self, resolution: SymbolResolution) -> None:
        for ref in resolution.references:
            entry = resolution.lookup(ref.name)
            if entry is None:
                resolution.errors.append(
                    f"unresolved symbol reference @{ref.name} in '{ref.user.name}'"
                )
                continue
            ref.target = entry.op

    # -- shorthand --------------------------------------------------------
    @property
    def resolution(self) -> SymbolResolution:
        return self.resolve()

    def lookup(self, name: str) -> Optional[SymbolEntry]:
        return self.resolve().lookup(name)

    def names(self) -> List[str]:
        return self.resolve().names()

    @property
    def num_resolved(self) -> int:
        return self.resolve().num_resolved

    def __len__(self) -> int:
        return len(self.resolve())

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<SymbolResolver root={self.root.name!r}>"


def resolve_symbols(root: Operation) -> SymbolResolution:
    """Convenience wrapper: ``resolve_symbols(module).num_resolved``."""
    return SymbolResolver(root).resolve()

